function roadPenalty(){if(player.license)return;player.cash=Math.max(0,player.cash-250);player.points+=3;notify('Sem CNH: multa de R$ 250 e +3 pontos!')}
function finishTarget(){let i=targets.findIndex(t=>Math.hypot(t.x-player.x,t.y-player.y)<45);if(i<0)return false;targets.splice(i,1);if(job?.type==='delivery'){player.cash+=45;player.deliveries++;job.left--;notify('Pedido entregue! +R$ 45.')}else if(job?.type==='taxi'){player.cash+=60;job.left--;notify('Passageiro chegou! +R$ 60.')}if(job&&job.left<=0){if(job.type==='delivery')player.cash+=70;notify('Corre completo! Bônus no bolso.');job=null;targets=[]}updateUI();return true}
function interact(){if(!gameOn)return;if(finishTarget())return;let v=nearestVehicle();if(v){if(player.vehicle===v){player.vehicle=null;player.ride='A PÉ';notify('Você desceu do veículo.')}else if(!v.owned){v.stolen=true;player.vehicle=v;player.x=v.x;player.y=v.y;player.ride=v.type==='moto'?'MOTO ROUBADA · 125cc':'CARRO ROUBADO · 1.6';player.heat=Math.min(100,player.heat+15);roadPenalty();if(player.license)notify('Veículo levado. A rua toda viu.')}else{player.vehicle=v;player.x=v.x;player.y=v.y;player.ride=v.type==='moto'?'MOBILETE · 49cc':'CARRO PRÓPRIO';roadPenalty();if(player.license)notify('Veículo ligado!')}return}let near=null,dist=100;for(let [k,p] of Object.entries(world.stations)){let d=Math.hypot(p.x-player.x,p.y-player.y);if(d<dist){near=k;dist=d}}if(near){openJob(near);return}notify('Chegue mais perto de um ponto, destino ou veículo.')}

