 function confirmJob(type){document.getElementById('jobModal').classList.add('hide');if(type==='delivery'){job={type:'delivery',left:3};spawnTargets(3,'delivery');notify('Rota ativada! Procure os marcadores amarelos.')}else if(type==='taxi'){job={type:'taxi',left:3};player.ride='SEDAN · TÁXI';spawnTargets(3,'taxi');notify('Taxímetro ligado. Leve os passageiros!')}else if(type==='chop'){let v=job?.vehicle;if(v){let amount=v.type==='moto'?250:500;player.cash+=amount;player.heat=Math.min(100,player.heat+30);vehicles=vehicles.filter(x=>x!==v);if(player.vehicle===v){player.vehicle=null;player.ride='A PÉ'}job=null;notify('Peças vendidas por R$ '+amount+'. Calor policial subiu!');updateUI()}else notify('Ache um veículo e traga até o desmanche.')}else if(type==='house'){player.energy=100;player.heat=0;notify('Descansou bem. Energia cheia, polícia perdeu seu rastro.')}else if(type==='dealer')openDealer()}
