 function openDealer(){document.getElementById('jobTitle').textContent='ESCOLHA SEU EQUIPAMENTO';document.getElementById('jobDesc').textContent='Uma habilitação abre portas — e evita multas. Equipamento é só visual, fica guardado.';document.getElementById('jobDetails').innerHTML='<button class="action" data-buy="cnh"><span><b>CNH A + B</b><small>R$ 800</small></span></button>'+weapons.map((w,i)=>'<button class="action" data-buy="'+(i+1)+'"><span><b>'+w.name+'</b><small>R$ '+w.price+'</small></span></button>').join('');document.getElementById('jobConfirm').classList.add('hide');document.querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>buyItem(b.dataset.buy))}
 function buyItem(item){if(item==='cnh'){if(player.cash<800){notify('Grana curta. Faça uns corres primeiro.');return}player.cash-=800;player.license=true;notify('Habilitação A/B emitida!')}else{let n=Number(item),w=weapons[n-1];if(player.cash<w.price){notify('Você não tem grana suficiente.');return}player.cash-=w.price;player.inventory.push(n);player.weapon=n;notify(w.name+' comprado e guardado.')}updateUI()}

